select json_build_object('version',version(),'server_settings',(select json_object_agg(name,setting) from pg_settings where name in ('server_version','TimeZone','max_connections','shared_buffers','default_transaction_read_only')),'roles',(select coalesce(json_agg(json_build_object('role',rolname,'superuser',rolsuper,'can_login',rolcanlogin,'bypass_rls',rolbypassrls) order by rolname),'[]'::json) from pg_roles where rolname in ('anon','authenticated','service_role','authenticator','postgres','supabase_admin','supabase_auth_admin','supabase_storage_admin','dashboard_user') )) as data;
